public class ReturnExamples
{
    // Returns a string
    public string GetGreeting(string name)
    {
        return $"Hello, {name}!";
    }

    // Returns a bool
    public bool IsAdult(int age)
    {
        return age >= 18;
    }

    // Returns a double
    public double CalculateArea(double radius)
    {
        return Math.PI * radius * radius;
    }

    // Void — no return value
    public void LogMessage(string message)
    {
        Console.WriteLine($"[LOG] {DateTime.Now}: {message}");
        // No return statement needed
    }

    // Early return
    public string GetDayName(int dayNumber)
    {
        if (dayNumber < 1 || dayNumber > 7)
        {
            return "Invalid day";  // Exit early
        }

        return dayNumber switch
        {
            1 => "Monday",
            2 => "Tuesday",
            3 => "Wednesday",
            4 => "Thursday",
            5 => "Friday",
            6 => "Saturday",
            7 => "Sunday",
            _ => "Unknown"
        };
    }
}

public class Greeter
{
    // Required parameter + optional parameter with default value
    public void Greet(string name, int repeatCount = 1, bool loudly = false)
    {
        for (int i = 0; i < repeatCount; i++)
        {
            string message = $"Hello, {name}!";
            if (loudly)
            {
                message = message.ToUpper();
            }
            Console.WriteLine(message);
        }
    }
}

// Calling with different combinations:
var greeter = new Greeter();
greeter.Greet("Alice");                    // Uses defaults: 1 time, not loudly
greeter.Greet("Bob", 3);                   // 3 times, not loudly
greeter.Greet("Charlie", loudly: true);   // Named argument: 1 time, loudly
greeter.Greet("Dana", 2, true);            // 2 times, loudly

public class Statistics
{
    // params allows passing any number of int arguments
    public int Sum(params int[] numbers)
    {
        int total = 0;
        foreach (int n in numbers)
        {
            total += n;
        }
        return total;
    }

    // Can also pass an existing array
    public double Average(params double[] values)
    {
        if (values.Length == 0) return 0;
        return values.Sum() / values.Length;
    }
}

// Usage
var stats = new Statistics();

int sum1 = stats.Sum(1, 2, 3, 4, 5);           // sum1 = 15
int sum2 = stats.Sum(10, 20);                   // sum2 = 30
int sum3 = stats.Sum();                         // sum3 = 0 (no arguments)

int[] values = { 1, 2, 3, 4, 5, 6 };
double avg = stats.Average(values);             // avg = 3.5

public class Printer
{
    // Overload 1: No parameters
    public void Print()
    {
        Console.WriteLine("(no message)");
    }

    // Overload 2: One string parameter
    public void Print(string message)
    {
        Console.WriteLine(message);
    }

    // Overload 3: String + integer for repeated printing
    public void Print(string message, int repeatCount)
    {
        for (int i = 0; i < repeatCount; i++)
        {
            Console.WriteLine(message);
        }
    }

    // Overload 4: Multiple values
    public void Print(string message, ConsoleColor color)
    {
        Console.ForegroundColor = color;
        Console.WriteLine(message);
        Console.ResetColor();
    }
}

// Usage
var printer = new Printer();
printer.Print();                        // (no message)
printer.Print("Hello!");                // Hello!
printer.Print("Spam", 3);               // Prints Spam 3 times
printer.Print("Alert!", ConsoleColor.Red); // Red Alert!

public class ReferenceExamples
{
    // ref: method reads and modifies the original variable
    public void DoubleValue(ref int value)
    {
        value *= 2;  // Modifies the caller's variable
    }

    // out: method must assign a value before returning
    public bool TryParseInt(string input, out int result)
    {
        result = 0;
        return int.TryParse(input, out result);
    }

    // in: method reads but cannot modify (good for large structs)
    public long CalculateDistance(in Point point1, in Point point2)
    {
        // point1.X = 5; // COMPILE ERROR: cannot modify in parameter
        long dx = point1.X - point2.X;
        long dy = point1.Y - point2.Y;
        return (long)Math.Sqrt(dx * dx + dy * dy);
    }
}

public readonly struct Point
{
    public int X { get; }
    public int Y { get; }
    public Point(int x, int y) => (X, Y) = (x, y);
}

// Usage:
int x = 5;
var examples = new ReferenceExamples();
examples.DoubleValue(ref x);
Console.WriteLine(x);  // Prints: 10

if (examples.TryParseInt("42", out int parsed))
{
    Console.WriteLine(parsed);  // Prints: 42
}

var p1 = new Point(0, 0);
var p2 = new Point(3, 4);
long dist = examples.CalculateDistance(in p1, in p2);
Console.WriteLine(dist);  // Prints: 5

public class RecursionExamples
{
    // Factorial: n! = n * (n-1)!
    // Base case: 0! = 1
    public int Factorial(int n)
    {
        // Base case: stop the recursion
        if (n <= 1)
        {
            return 1;
        }

        // Recursive case: n! = n * (n-1)!
        return n * Factorial(n - 1);
    }

    // Fibonacci sequence
    public int Fibonacci(int n)
    {
        if (n <= 0) return 0;
        if (n == 1) return 1;

        return Fibonacci(n - 1) + Fibonacci(n - 2);
    }

    // Sum of digits using recursion
    public int SumDigits(int number)
    {
        if (number == 0) return 0;
        return (number % 10) + SumDigits(number / 10);
    }
}

// Usage
var recursion = new RecursionExamples();
Console.WriteLine(recursion.Factorial(5));  // 120 (5*4*3*2*1)
Console.WriteLine(recursion.Fibonacci(6));   // 8 (0,1,1,2,3,5,8)
Console.WriteLine(recursion.SumDigits(12345)); // 15 (1+2+3+4+5)

public class Circle
{
    private double _radius;

    public Circle(double radius)
    {
        _radius = radius;
    }

    // Expression-bodied property
    public double Area => Math.PI * _radius * _radius;

    // Expression-bodied method
    public double Circumference => 2 * Math.PI * _radius;

    // Expression-bodied method with parameter
    public bool Contains(Point point) =>
        Math.Pow(point.X, 2) + Math.Pow(point.Y, 2) <= Math.Pow(_radius, 2);

    // Expression-bodied constructor
    public Circle() : this(1.0) { }
}

