public class DataProcessor
{
    public void ProcessNumbers(int[] numbers)
    {
        // Local function: only visible inside ProcessNumbers
        bool IsPrime(int n)
        {
            if (n <= 1) return false;
            if (n == 2) return true;
            if (n % 2 == 0) return false;

            for (int i = 3; i <= Math.Sqrt(n); i += 2)
            {
                if (n % i == 0) return false;
            }
            return true;
        }

        // Another local function using the outer variable
        void PrintPrime(int n)
        {
            Console.WriteLine($"{n} is prime!");
        }

        // Use the local functions
        foreach (int num in numbers)
        {
            if (IsPrime(num))
            {
                PrintPrime(num);
            }
        }
    }
}

// Usage
var processor = new DataProcessor();
processor.ProcessNumbers(new[] { 1, 2, 3, 4, 5, 17, 20 });
// Output: 2 is prime!
//         3 is prime!
//         5 is prime!
//         17 is prime!
